const initSqlJs = require('sql.js');
const fs = require('fs');

async function main() {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // List all tables
  const tables = db.exec(\"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name\");
  console.log('Tables:', tables[0].values.map(r => r[0]).join(', '));
}
main();
"

cd /tmp && npm init -y 2>/dev/null && npm install sql.js 2>/dev/null && node -e "
const initSqlJs = require('/tmp/node_modules/sql.js');
const fs = require('fs');

async function main() {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  const tables = db.exec(\"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name\");
  console.log('Tables:', tables[0].values.map(r => r[0]).join(', '));

  // Search for the order
  try {
    const orders = db.exec(\"SELECT * FROM orders WHERE order_id = '#W4407627' OR order_id = 'W4407627' LIMIT 5\");
    if (orders.length) { console.log('\\nOrder columns:', orders[0].columns); orders[0].values.forEach(r => console.log(r)); }
  } catch(e) {
    // Try to find orders table
    const t2 = db.exec(\"SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%order%'\");
    console.log('Order tables:', t2[0]?.values);
  }
}
main();
"

node -e "
const initSqlJs = require('/tmp/node_modules/sql.js');
const fs = require('fs');

async function main() {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // Get order items
  const items = db.exec(\"SELECT * FROM order_items WHERE order_id = '#W4407627'\");
  if (items.length) { console.log('Order Items columns:', items[0].columns); items[0].values.forEach(r => console.log(r)); }

  // Get product info
  const products = db.exec(\"SELECT * FROM products WHERE name LIKE '%Crew Tee%' OR product_id IN (SELECT product_id FROM order_items WHERE order_id = '#W4407627')\");
  if (products.length) { console.log('\\nProduct columns:', products[0].columns); products[0].values.forEach(r => console.log(r)); }

  // Get variants for this product
  const variants = db.exec(\"SELECT * FROM rt_variants WHERE product_id IN (SELECT product_id FROM order_items WHERE order_id = '#W4407627')\");
  if (variants.length) { console.log('\\nVariant columns:', variants[0].columns); variants[0].values.forEach(r => console.log(r)); }
}
main();
"
